/**
 * Closing a workspace is final and immediate: it leaves every member's list,
 * cannot be opened, joined or billed, and nothing is produced for it afterwards
 * — while other workspaces, even ones sharing members with it, carry on.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { hashToken } from "@/lib/hash";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import { runWebhookDeliveryJob } from "@/server/jobs/webhook-delivery-job";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { changePlan } from "@/server/services/billing-service";
import { acceptInvitation } from "@/server/services/invitation-service";
import { resolveActor } from "@/server/services/member-service";
import { notify } from "@/server/services/notification-service";
import {
  createOrganization,
  deleteOrganization,
  getOrganizationSummary,
  listOrganizationsForUser,
  resolveOrgBySlug,
} from "@/server/services/organization-service";
import { registerWebhookListeners } from "@/server/services/webhook-service";
import { resolveActorForOrg, switchActiveOrg } from "@/server/services/session-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { SessionPrincipal } from "@/types/member";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

const NOW = new Date("2026-06-01T07:00:00.000Z");
const PAST = "2026-01-01T00:00:00.000Z";
const AFTER_TRIAL = new Date("2026-12-31T00:00:00.000Z");

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

function principalFor(tenant: Tenant, role: "owner" | "member" = "member"): SessionPrincipal {
  return {
    userId: tenant.userIds[role],
    email: `${role}@${tenant.org.slug}.test`,
    activeOrgId: tenant.org.id,
    expiresAt: toIsoTimestamp(new Date(Date.now() + 3_600_000)),
  };
}

async function close(tenant: Tenant) {
  return deleteOrganization(tenant.actors.owner, {
    orgId: tenant.org.id,
    confirmSlug: tenant.org.slug,
  });
}

describe("closing a workspace", () => {
  it("archives the org and ends its subscription at the same moment", async () => {
    const tenant = await createTenant("close-basic");

    const closed = await close(tenant);
    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);

    expect(closed.archivedAt).not.toBeNull();
    expect(subscription?.status).toBe("canceled");
    expect(subscription?.cancelAt).toBe(closed.archivedAt);
  });

  it("refuses a second close as a conflict", async () => {
    const tenant = await createTenant("close-twice");
    await close(tenant);

    const again = close(tenant);

    await expect(again).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(again).rejects.toMatchObject({ code: "conflict" });
  });

  it("refuses a wrong confirmation without closing anything", async () => {
    const tenant = await createTenant("close-wrong");

    await expect(
      deleteOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        confirmSlug: "not-the-slug",
      }),
    ).rejects.toThrow(/confirmation/);

    expect((await orgRepo.findOrgById(tenant.org.id))?.archivedAt).toBeNull();
    expect((await subscriptionRepo.findSubscription(tenant.org.id))?.status).toBe("trialing");
  });

  it("keeps the address reserved and hands a new workspace another one", async () => {
    const tenant = await createTenant("close-slug");
    await close(tenant);

    const created = await createOrganization(tenant.userIds.owner, {
      name: "Reborn",
      slug: "close-slug",
      plan: "free",
    });

    expect(created.slug).not.toBe("close-slug");
    expect((await orgRepo.findOrgBySlug("close-slug"))?.id).toBe(tenant.org.id);
  });
});

describe("a closed workspace cannot be reached", () => {
  it("leaves every member's list but not the lists of other workspaces", async () => {
    const closing = await createTenant("reach-closing");
    const other = await createTenant("reach-other");
    // The same person is a member of both workspaces.
    await memberRepo.insertMember(other.org.id, closing.userIds.member, "member", null);

    await close(closing);

    const list = await listOrganizationsForUser(closing.userIds.member);
    expect(list.map((org) => org.id)).toEqual([other.org.id]);
    expect(await listOrganizationsForUser(closing.userIds.owner)).toEqual([]);
  });

  it("refuses actors, lookups and switching, even for a session valid before", async () => {
    const closing = await createTenant("reach-actor");
    const other = await createTenant("reach-actor-other");
    await memberRepo.insertMember(other.org.id, closing.userIds.member, "member", null);
    const principal = principalFor(closing);

    expect(await resolveActorForOrg(principal, closing.org.slug)).not.toBeNull();

    await close(closing);

    expect(await resolveActorForOrg(principal, closing.org.slug)).toBeNull();
    expect(await resolveActorForOrg(principal, closing.org.slug, { includeClosed: true })).not.toBeNull();
    expect(await resolveActor(closing.userIds.member, closing.org.id)).toBeNull();
    expect(await resolveOrgBySlug(closing.org.slug)).toBeNull();
    await expect(switchActiveOrg(principal, { orgId: closing.org.id })).rejects.toThrow();
    await expect(getOrganizationSummary(closing.actors.member, closing.org.id)).rejects.toThrow();

    // The other workspace is untouched.
    const elsewhere = await resolveActorForOrg(principal, other.org.slug);
    expect(elsewhere?.orgId).toBe(other.org.id);
    await expect(switchActiveOrg(principal, { orgId: other.org.id })).resolves.toBeUndefined();
  });

  it("refuses an invitation sent before it closed, and tells nobody a member joined", async () => {
    const tenant = await createTenant("reach-invite");
    const invitee = await userRepo.insertUser({
      email: "late@reach-invite.test",
      name: "Late",
      passwordHash: "seed",
    });
    await invitationRepo.insertInvitation(
      tenant.org.id,
      { orgId: tenant.org.id, email: invitee.email, role: "member", expiresInDays: 14 },
      tenant.userIds.owner,
      hashToken("invite-token-before-close"),
    );

    await close(tenant);

    await expect(
      acceptInvitation(invitee.id, { token: "invite-token-before-close" }),
    ).rejects.toThrow();
    expect(await memberRepo.findMember(tenant.org.id, invitee.id)).toBeNull();
  });
});

describe("nothing is produced for a closed workspace", () => {
  it("sends no notifications, but still notifies elsewhere", async () => {
    const closing = await createTenant("quiet-notify");
    const other = await createTenant("quiet-notify-other");
    const payload = { title: "t", body: "b", href: "/x", actorId: null };

    await close(closing);

    expect(await notify(closing.org.id, "issue_overdue", [closing.userIds.member], payload)).toEqual([]);
    expect(await notify(other.org.id, "issue_overdue", [other.userIds.member], payload)).toHaveLength(1);
  });

  it("skips the workspace in the overdue sweep", async () => {
    const closing = await createTenant("quiet-overdue");
    const other = await createTenant("quiet-overdue-other");
    const issues: string[] = [];
    for (const tenant of [closing, other]) {
      await usageRepo.recomputeUsage(tenant.org.id);
      const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
      const issue = await issueRepo.insertIssue(
        issueInput(tenant.org.id, tenant.project.id, {
          assigneeId: tenant.userIds.member,
          dueAt: PAST,
        }),
        tenant.userIds.owner,
        number,
      );
      issues.push(issue.id);
    }

    await close(closing);

    const seen: string[] = [];
    detachers.push(subscribe("issue.overdue", (payload) => void seen.push(payload.issueId)));
    await runOverdueIssueJob(NOW);

    expect(seen).toEqual([issues[1]]);
  });

  it("leaves its webhook deliveries queued before the closing undelivered", async () => {
    const closing = await createTenant("quiet-hooks");
    const other = await createTenant("quiet-hooks-other");
    const deliveries = [];
    for (const tenant of [closing, other]) {
      const endpoint = await webhookRepo.insertEndpoint(
        {
          orgId: tenant.org.id,
          url: "https://example.test/hook",
          eventTypes: ["issue.created"],
        },
        "secret",
      );
      deliveries.push(
        await webhookRepo.enqueueDelivery(tenant.org.id, endpoint.id, "issue.created", "{}"),
      );
    }

    await close(closing);
    const result = await runWebhookDeliveryJob(NOW);

    expect(result.failed).toBe(0);
    const pending = await webhookRepo.claimPendingDeliveries(100);
    expect(pending.map((row) => row.id)).not.toContain(deliveries[0]?.id);
    expect(result.processed).toBe(1);
  });

  it("queues no new deliveries for it", async () => {
    const closing = await createTenant("quiet-enqueue");
    await webhookRepo.insertEndpoint(
      {
        orgId: closing.org.id,
        url: "https://example.test/hook",
        eventTypes: ["billing.plan_changed"],
      },
      "secret",
    );
    await close(closing);
    const off = registerWebhookListeners();
    detachers.push(off);

    const { emit } = await import("@/lib/event-bus");
    await emit("billing.plan_changed", {
      orgId: closing.org.id,
      actorId: null,
      occurredAt: toIsoTimestamp(NOW),
      from: "growth",
      to: "free",
    });

    expect(await webhookRepo.claimPendingDeliveries(100)).toEqual([]);
  });

  it("records no plan change when the trial would have ended", async () => {
    const closing = await createTenant("quiet-trial");
    const other = await createTenant("quiet-trial-other");
    await usageRepo.recomputeUsage(closing.org.id);
    await usageRepo.recomputeUsage(other.org.id);
    await close(closing);

    const changes: string[] = [];
    detachers.push(subscribe("billing.plan_changed", (payload) => void changes.push(payload.orgId)));
    await runTrialExpiryJob(AFTER_TRIAL);

    expect(changes).toEqual([other.org.id]);
    const subscription = await subscriptionRepo.findSubscription(closing.org.id);
    expect(subscription?.plan).toBe("growth");
    expect(subscription?.status).toBe("canceled");
    expect(await activityRepo.listActivityForSubject(closing.org.id, "subscription", closing.org.id)).toEqual([]);
  });

  it("refuses a plan change even for an actor built before the closing", async () => {
    const closing = await createTenant("quiet-plan");
    await close(closing);

    await expect(
      changePlan(closing.actors.owner, { orgId: closing.org.id, plan: "free", interval: "monthly" }),
    ).rejects.toThrow();
  });

  it("skips it in the background jobs, including a search reindex", async () => {
    const closing = await createTenant("quiet-jobs");
    await usageRepo.recomputeUsage(closing.org.id);
    await close(closing);

    expect(await usageRepo.listOrgIdsForRollup(100)).not.toContain(closing.org.id);
    const rollup = await runUsageRollupJob(NOW);
    expect(rollup.failed).toBe(0);
    const reindex = await runSearchReindexJob(closing.org.id);
    expect(reindex.processed).toBe(0);
  });
});

