describe("a closed workspace cannot be reached", () => {
  it("leaves every member's list but not the lists of other workspaces", async () => {
    const closing = await createTenant("reach-closing");
    const other = await createTenant("reach-other");
    // The same person is a member of both workspaces.
    await memberRepo.insertMember(other.org.id, closing.userIds.member, "member", null);

    await close(closing);

    const list = await listOrganizationsForUser(closing.userIds.member);
    expect(list.map((org) => org.id)).toEqual([other.org.id]);
    expect(await listOrganizationsForUser(closing.userIds.owner)).toEqual([]);
  });

  it("refuses actors, lookups and switching, even for a session valid before", async () => {
    const closing = await createTenant("reach-actor");
    const other = await createTenant("reach-actor-other");
    await memberRepo.insertMember(other.org.id, closing.userIds.member, "member", null);
